function escCupao(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
async function load(){const r=await apiFetch('/operacoes/admin/cupons');document.getElementById('count').textContent=r.filter(x=>x.ativo).length+' cupões ativos';document.getElementById('rows').innerHTML=r.length?r.map(c=>`<tr><td>${escCupao(c.codigo)}</td><td>${escCupao(c.tipo)}</td><td>${Number(c.valor).toFixed(2)}${c.tipo==='percentagem'?'%':' €'}</td><td>${c.usos_atuais}${c.usos_maximos?'/'+c.usos_maximos:''}</td><td>${c.ativo?'Ativo':'Inativo'}</td><td><button onclick="toggleCoupon(${c.id},${!c.ativo})">${c.ativo?'Desativar':'Ativar'}</button></td></tr>`).join(''):'<tr><td colspan="5">Ainda não existem cupões.</td></tr>'}document.getElementById('criar').onclick=async()=>{try{await apiFetch('/operacoes/admin/cupons',{method:'POST',body:JSON.stringify({codigo:codigo.value,tipo:tipo.value,valor:Number(valor.value),usosMaximos:max.value||null})});msg.textContent='Cupão criado.';load()}catch(e){msg.textContent=e.message}};load().catch(e=>msg.textContent=e.message);async function toggleCoupon(id,ativo){try{await apiFetch('/operacoes/admin/cupons/'+id,{method:'PUT',body:JSON.stringify({ativo})});load()}catch(e){msg.textContent=e.message}};
